def forward(groups):
    value = int(groups[1])
    spaces_before = len(groups[0])
    spaces_after = len(groups[2])
    return {'stored': [value], 'layout': [spaces_before, spaces_after]}

def inverse(record):
    spaces_before = ' ' * record['layout'][0]
    spaces_after = ' ' * record['layout'][1]
    value = str(record['stored'][0])
    return f'took{spaces_before}{value}{spaces_after}ms'
